@startuml

class Center {
  + Name : string
}

class Room {
  + Number : int
  + MaxCapacity : int
}

class Person {
  + FirstName : string
  + FamilyName : string
  + BirthDate : date
}

class Trainer extends Person {
  + Diploma : string
}

class Session {
  + Date : date
  + StartHour : time
}

class IndividualSession extends Session {}

class GroupSession extends Session {
  + Type : string
}

class Member extends Person {}

Center "1" *-- "1..*" Room
Room "1" -- "0..*" Session

GroupSession "*" -- "1" Trainer
Session "*" -- "0..*" Member

Trainer "0..*" -- "0..*" Session : supervises
@enduml

